mapper.select:
SELECT A.MHS_CONNSEQ, C.MHS_CLASSCD, C.MHS_CLASSROOMNM, C.MHS_CLASSNM, C.MHS_TEACHERNM, C.MHS_CLASSSTARTDAY, C.MHS_CLASSENDDAY, C.MHS_CLASSDAYOFWEEK, C.MHS_CLASSSTARTTIME, C.MHS_CLASSENDTIME, C.MHS_CLASSINTRO FROM TB_MHSVIEWCONNINFO A JOIN TB_MHSMONITORINFO B ON A.MHS_MONITORCD = B.MHS_MONITORCD JOIN TB_MHSCLASSINFO C ON A.MHS_CLASSCD = C.MHS_CLASSCD WHERE C.MHS_CLASSSTATUS != 'N' AND A.MHS_MONITORCD = #{mhsMonitorcd}
AND #{searchDay} BETWEEN C.MHS_CLASSSTARTDAY AND C.MHS_CLASSENDDAY AND C.MHS_CLASSDAYOFWEEK ~ TO_CHAR(TO_DATE(#{searchDay}, 'YYYYMMDD'), 'D')
ORDER BY C.MHS_CLASSSTARTTIME ASC, A.MHS_CONNSEQ DESC
